            for (int i = 0; i < props.length; i++) {
                final PropertyDescriptor prop = props[i];
                final Method reader = prop.getReadMethod();

                // Check for @Column annotations as explicit marks
                final Column column;
                if (reader != null) {
                    column = reader.getAnnotation(Column.class);
